const mod=await ctx.utils.import("https://esm.sh/three@0.186.0");const T=mod.default??mod;
const renderer=new T.WebGLRenderer({canvas:ctx.canvas,context:ctx.gl,antialias:true});renderer.setPixelRatio(1);
const scene=new T.Scene();scene.background=new T.Color(0x101821);
scene.add(new T.HemisphereLight(0xffffff,0x334455,2));
const light=new T.DirectionalLight(0xffffff,3);light.position.set(3,5,6);scene.add(light);
const camera=new T.PerspectiveCamera(42,1,0.1,50);
Object.assign(ctx.state,{T,renderer,scene,camera,size:[0,0],orbit:ctx.utils.createOrbitCamera({distance:8,theta:-0.65,phi:1.15,fov:42,near:0.1,far:50,minDistance:4,maxDistance:14})});
const geometry=new T.CylinderGeometry(0.4,0.4,4,24,40);const pos=geometry.attributes.position,indices=[],weights=[];
for(let i=0;i<pos.count;i++){const y=Math.max(0,Math.min(4,pos.getY(i)+2));const b=Math.min(3,Math.floor(y));const f=y-b;indices.push(b,b+1,0,0);weights.push(1-f,f,0,0);if(Math.abs((1-f)+f-1)>1e-6)throw Error("invalid weights");}
geometry.setAttribute('skinIndex',new T.Uint16BufferAttribute(indices,4));geometry.setAttribute('skinWeight',new T.Float32BufferAttribute(weights,4));
const bones=[];for(let i=0;i<5;i++){const b=new T.Bone();b.position.y=i===0?-2:1;if(i)bones[i-1].add(b);bones.push(b);}
const mesh=new T.SkinnedMesh(geometry,new T.MeshStandardMaterial({color:0x25cbbb,roughness:0.35,metalness:0.1}));mesh.add(bones[0]);const skeleton=new T.Skeleton(bones);mesh.bind(skeleton);mesh.frustumCulled=false;scene.add(mesh);
const helper=new T.SkeletonHelper(mesh);helper.material.depthTest=false;helper.renderOrder=2;scene.add(helper);
// Verify Three's CPU skin transform moves a tip vertex when a bone rotates.
let tip=0;for(let i=0;i<pos.count;i++)if(pos.getY(i)>pos.getY(tip))tip=i;
const rest=new T.Vector3().fromBufferAttribute(pos,tip);bones[1].rotation.z=0.5;mesh.updateMatrixWorld(true);skeleton.update();const bent=mesh.applyBoneTransform(tip,rest.clone());if(bent.distanceTo(rest)<0.5)throw Error('skin deformation failed');bones[1].rotation.z=0;mesh.updateMatrixWorld(true);
Object.assign(ctx.state,{mesh,bones,skeleton,helper});ctx.publish('bones',5);ctx.publish('skin check displacement',bent.distanceTo(rest));
